        if (visited[i]) continue;
        visited[i] = true;
        count++;

        for (int j = i + 1; j < N; j++) {
            if (visited[j]) continue;
            visited[j] = true;
            count++;

            for (int k = j + 1; k < N; k++) {
                if (visited[k]) continue;
                visited[k] = true;
                count++;

                if (squared(A[i] + A[j]) && squared(A[j] + A[k]) && squared(A[k] + A[i])) {
                    count++;
                }
            }
        }
    }

    return count;
}

