        if (s.charAt(i) == currentChar) {
            currentEnd += 1;
        } else {
            if (currentEnd - currentStart > energy) {
                energy = currentEnd - currentStart;
            }
            currentChar = s.charAt(i);
            currentStart = i;
            currentEnd = i;
        }
